WITH filtered_web_events AS (SELECT * FROM web_events WHERE session_id IN (25, 26)), web_events_stats AS (SELECT QUARTER(event_time) event_quarter, CASE WHEN duration_sec >= 387 THEN 'high' WHEN duration_sec >= 193 THEN 'mid' ELSE 'low' END duration_sec_bucket, COUNT(CASE WHEN page = '/cart' THEN 1 END) cart_count, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(event_type))) event_type_values FROM filtered_web_events GROUP BY QUARTER(event_time), CASE WHEN duration_sec >= 387 THEN 'high' WHEN duration_sec >= 193 THEN 'mid' ELSE 'low' END) SELECT event_quarter, duration_sec_bucket, cart_count, event_type_values FROM web_events_stats;
